package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"mime"
	"mime/multipart"
	"net/http"
	"net/smtp"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

const (
	maxUploadSize = 10 << 20 // 10MB
	uploadDir     = "/var/mail-attachments"
	smtpHost      = "localhost"
	smtpPort      = "25"
)

type AttachmentMeta struct {
	OriginalName string
	SafePath     string
	ContentType  string
	Size         int64
}

type MailRequest struct {
	To          string
	Subject     string
	Body        string
	Attachments []AttachmentMeta
}

var (
	pendingMails = make(map[string]*MailRequest)
	pendingMu    sync.RWMutex
)

func generateToken() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func sanitizeFilename(name string) string {
	name = filepath.Base(name)
	name = strings.ReplaceAll(name, "..", "")
	name = strings.Map(func(r rune) rune {
		if r == '/' || r == '\\' || r == '\x00' {
			return -1
		}
		return r
	}, name)
	return name
}

func resolveContentType(filename string) string {
	ext := filepath.Ext(filename)
	ct := mime.TypeByExtension(ext)
	if ct == "" {
		ct = "application/octet-stream"
	}
	return ct
}

func validateRecipient(email string) bool {
	parts := strings.Split(email, "@")
	if len(parts) != 2 {
		return false
	}
	if len(parts[0]) == 0 || len(parts[1]) == 0 {
		return false
	}
	if strings.ContainsAny(email, "\r\n") {
		return false
	}
	return true
}

func processUpload(part *multipart.Part) (*AttachmentMeta, error) {
	origName := sanitizeFilename(part.FileName())
	if origName == "" || origName == "." {
		return nil, fmt.Errorf("invalid filename")
	}

	token := generateToken()
	safeName := token + "_" + origName
	safePath := filepath.Join(uploadDir, safeName)

	dst, err := os.OpenFile(safePath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return nil, err
	}
	defer dst.Close()

	written, err := io.Copy(dst, io.LimitReader(part, maxUploadSize))
	if err != nil {
		os.Remove(safePath)
		return nil, err
	}

	return &AttachmentMeta{
		OriginalName: origName,
		SafePath:     safePath,
		ContentType:  resolveContentType(origName),
		Size:         written,
	}, nil
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxUploadSize+4096)

	to := r.Header.Get("X-Mail-To")
	subject := r.Header.Get("X-Mail-Subject")

	if !validateRecipient(to) {
		http.Error(w, "Invalid recipient", 400)
		return
	}

	reader, err := r.MultipartReader()
	if err != nil {
		http.Error(w, "Invalid multipart", 400)
		return
	}

	var attachments []AttachmentMeta
	var body string

	for {
		part, err := reader.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			http.Error(w, "Read error", 500)
			return
		}

		if part.FormName() == "body" {
			buf := make([]byte, 4096)
			n, _ := io.ReadFull(part, buf)
			body = string(buf[:n])
			continue
		}

		if part.FileName() != "" {
			meta, err := processUpload(part)
			if err != nil {
				http.Error(w, "Upload failed: "+err.Error(), 500)
				return
			}
			attachments = append(attachments, *meta)
		}
	}

	mailReq := &MailRequest{
		To:          to,
		Subject:     subject,
		Body:        body,
		Attachments: attachments,
	}

	token := generateToken()
	pendingMu.Lock()
	pendingMails[token] = mailReq
	pendingMu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"token":"%s","status":"pending"}`, token)
}

func handleConfirm(w http.ResponseWriter, r *http.Request) {
	token := r.URL.Query().Get("token")
	if token == "" {
		http.Error(w, "Missing token", 400)
		return
	}

	pendingMu.Lock()
	mailReq, exists := pendingMails[token]
	if exists {
		delete(pendingMails, token)
	}
	pendingMu.Unlock()

	if !exists {
		http.Error(w, "Invalid or expired token", 404)
		return
	}

	err := sendMail(mailReq)
	if err != nil {
		http.Error(w, "Send failed", 500)
		return
	}

	for _, att := range mailReq.Attachments {
		os.Remove(att.SafePath)
	}

	fmt.Fprintf(w, `{"status":"sent"}`)
}

func sendMail(req *MailRequest) error {
	boundary := generateToken()
	var msg strings.Builder

	msg.WriteString(fmt.Sprintf("To: %s\r\n", req.To))
	msg.WriteString(fmt.Sprintf("Subject: %s\r\n", req.Subject))
	msg.WriteString(fmt.Sprintf("MIME-Version: 1.0\r\n"))
	msg.WriteString(fmt.Sprintf("Content-Type: multipart/mixed; boundary=%s\r\n", boundary))
	msg.WriteString("\r\n")

	msg.WriteString(fmt.Sprintf("--%s\r\n", boundary))
	msg.WriteString("Content-Type: text/plain; charset=utf-8\r\n\r\n")
	msg.WriteString(req.Body)
	msg.WriteString("\r\n")

	for _, att := range req.Attachments {
		data, err := os.ReadFile(att.SafePath)
		if err != nil {
			continue
		}
		msg.WriteString(fmt.Sprintf("--%s\r\n", boundary))
		msg.WriteString(fmt.Sprintf("Content-Type: %s\r\n", att.ContentType))
		msg.WriteString(fmt.Sprintf("Content-Disposition: attachment; filename=\"%s\"\r\n", att.OriginalName))
		msg.WriteString("Content-Transfer-Encoding: base64\r\n\r\n")
		msg.WriteString(hex.EncodeToString(data))
		msg.WriteString("\r\n")
	}

	msg.WriteString(fmt.Sprintf("--%s--\r\n", boundary))

	return smtp.SendMail(
		smtpHost+":"+smtpPort,
		nil,
		"noreply@service.local",
		[]string{req.To},
		[]byte(msg.String()),
	)
}

func main() {
	os.MkdirAll(uploadDir, 0700)
	http.HandleFunc("/upload", handleUpload)
	http.HandleFunc("/confirm", handleConfirm)
	fmt.Println("Mail service listening on :8080")
	http.ListenAndServe(":8080", nil)
}
